gamE(){return"\u0421\u0438\u0433\u043d\u0430\u043b\u0438\u0437\u0438\u0440\u0430\u0439"},
gblR(){return"\u041f\u043e\u0434\u0434\u0440\u044a\u0436\u043a\u0430\u0442\u0430 \u0433\u043e \u043f\u0440\u0435\u0433\u043b\u0435\u0436\u0434\u0430 \u0434\u043e 72 \u0447\u0430\u0441\u0430 \u0438 \u0440\u0435\u0448\u0430\u0432\u0430 \u0441 \u043c\u043e\u0442\u0438\u0432\u0438. \u0421\u0438\u0433\u043d\u0430\u043b \u0441\u0430\u043c \u043f\u043e \u0441\u0435\u0431\u0435 \u0441\u0438 \u043d\u0435 \u0441\u0432\u0430\u043b\u044f \u043d\u0438\u0449\u043e."},
gamG(){return"\u041a\u0430\u043a\u0432\u043e \u043d\u0435 \u0435 \u043d\u0430\u0440\u0435\u0434 (\u043f\u043e \u0436\u0435\u043b\u0430\u043d\u0438\u0435)"},
