gblS(){return u.ab},
gamC(){return"\u041e\u0449\u0435"},
ga2Q(){return"\u0411\u0438\u0432\u0448 \u043f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b"},
gble(){return"\u041f\u043e\u0442\u0432\u044a\u0440\u0434\u0435\u043d \u043f\u0440\u0435\u0441\u0442\u043e\u0439"},
bm4(a){return"\u0411\u0435\u043b\u0435\u0436\u043a\u0430 \u043d\u0430 Stavia: \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u044a\u0442 \u0431\u0435\u0448\u0435 \u043d\u0430\u0448, \u043d\u0435 \u043d\u0430 \u043e\u0431\u0435\u043a\u0442\u0430; \u043d\u0435 \u0432\u043b\u0438\u0437\u0430 \u0432 \u0441\u0440\u0435\u0434\u043d\u0430\u0442\u0430. "+a},
