amW(a){return"\u041f\u043b\u0430\u0449\u0430\u0448 \u043d\u0430 \u043c\u044f\u0441\u0442\u043e \u043f\u0440\u0438 \u0438\u0437\u043b\u0438\u0437\u0430\u043d\u0435: "+a+"."},
bob(a,b){return"\u041f\u043b\u0430\u0442\u0435\u043d\u043e \u043d\u0430 \u043c\u044f\u0441\u0442\u043e \xb7 "+a+" \xb7 "+b},
